paths={}; operations=[]
def paginated(name):
 key=name+'Page'
 if key not in S:define(key,{'items':arr(ref(name)),'next_cursor':nullable(text)})
 return key
def route(method,path,op,response=None,request=None,code=200,role='viewer',city=False,paging=False,query=None,etag=False,conditional=False,public=False,mime='application/json',desc=None):
 params=[]
 import re
 for name in re.findall(r'{([^}]+)}',path):params.append({'name':name,'in':'path','required':True,'schema':uid if name!='z' and name!='x' and name!='y' else integer(minimum=0)})
 if city:params.append({'name':'city_id','in':'query','required':True,'schema':uid})
 if paging:params.extend([{'name':'cursor','in':'query','schema':text},{'name':'limit','in':'query','schema':integer(minimum=1,maximum=200,default=50)}])
 for name,schema in (query or {}).items():params.append({'name':name,'in':'query','schema':schema})
 if method not in ['get','head']:
  params.extend([{'name':'X-CSRF-Token','in':'header','required':True,'schema':text},{'name':'Idempotency-Key','in':'header','required':True,'schema':st(minLength=8,maxLength=128)}])
 if conditional:params.append({'name':'If-Match','in':'header','required':True,'schema':text})
 result={'description':desc or 'Successful response'}
 if response:result['content']={mime:{'schema':ref(response)}}
 if etag:result['headers']={'ETag':{'description':'Opaque quoted revision token. Return unchanged in If-Match.','schema':text}}
 item={'operationId':op,'summary':op,'x-required-role':role,'parameters':params,'responses':{str(code):result,'default':{'description':'Structured API error; includes 401/403/404/409/412/422/429/503 as applicable.','content':{'application/problem+json':{'schema':ref('Problem')}}}}}
 if request:item['requestBody']={'required':True,'content':{'application/json':{'schema':ref(request)}}}
 if public:item['security']=[]
 paths.setdefault(path,{})[method]=item
 operations.append({'operation_id':op,'method':method.upper(),'path':path,'minimum_role':role,'request_schema':request,'response_schema':response,'success_status':code})

