# BFF/OIDC handshake is intentionally not a user/password API.
for path,op in [('/auth/login','startOidcLogin'),('/auth/callback','completeOidcLogin')]:
 route('get',path,op,None,code=302,public=True,desc='OIDC redirect with server-side state/nonce validation; session HttpOnly cookie on successful callback.')
 paths[path]['get']['responses']['302']['headers']={'Location':{'schema':st(format='uri-reference'),'description':'Allowlisted same-origin destination or configured OIDC provider.'}}
 if path.endswith('callback'):paths[path]['get']['parameters']=[{'name':k,'in':'query','required':True,'schema':text} for k in ['code','state']]
route('post','/auth/logout','logout',None,None,204,'viewer')

